package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.Venda; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface VendaRepository extends JpaRepository<Venda,String> { Optional<Venda> findByIdempotencyKey(String key); @EntityGraph(attributePaths={"cliente","vendedor","itens","itens.produto"}) @Query("select v from Venda v where v.id=:id") Optional<Venda> detail(@Param("id")String id); @Query("select coalesce(sum(v.totalVenda),0) from Venda v where v.status='FINALIZADA' and v.dataVenda between :from and :to") BigDecimal totalFinalized(@Param("from")LocalDate from,@Param("to")LocalDate to); @Query("select v from Venda v where v.cliente.id=:clientId and v.status='FINALIZADA' order by v.dataVenda desc") List<Venda> finalizedByClient(@Param("clientId")String clientId); @Query("select v from Venda v join fetch v.cliente order by v.dataVenda desc") List<Venda> listWithClient(); @Query("select coalesce(sum(i.quantidade*coalesce(i.custoUnitario,0)),0) from VendaItem i where i.venda.status='FINALIZADA' and i.venda.dataVenda between :from and :to") BigDecimal costOfGoodsSold(@Param("from")LocalDate from,@Param("to")LocalDate to); }